<?php
/**
 * Tests that the readme discloses exactly the service the gateway declares
 *
 * @package SEOCart\GatewayForStripe
 * @since   0.2.0
 * @license GPL-3.0-or-later
 */

declare( strict_types=1 );

namespace SEOCart\GatewayForStripe\Tests\Unit;

use SEOCart\GatewayForStripe\Tests\Support\GatewayTestCase;
use SEOCart\Tools\Docs\ExternalServicesSection;

/**
 * The "External services" section of readme.txt is generated by SEOCart's own generator from the hosts the gateway
 * declares; this test fails when the two drift apart, and its message is the section to paste.
 *
 * Planted violation, shown red and removed: a sentence of the section edited by hand: the test fails.
 *
 * @since 0.2.0
 */
final class ExternalServicesTest extends GatewayTestCase {

	/**
	 * Tests that the readme's section is the generator's output over the gateway's hosts.
	 *
	 * @since 0.2.0
	 */
	public function test_the_readme_discloses_the_declared_hosts(): void {
		$readme    = (string) file_get_contents( dirname( __DIR__, 2 ) . '/readme.txt' );
		$generator = new ExternalServicesSection( $this->gateway->describe()->hosts );

		$this->assertSame( $generator->generate( $readme )->content, $readme, "readme.txt's External services section must read:\n\n" . $generator->render() );
	}
}
